SET LOCAL search_path = pg_catalog;

CREATE UNIQUE INDEX notifications_kind_key_uq ON ctrlz.notifications (tenant_id, kind, (params ->> 'key'))
  WHERE (params ->> 'key') IS NOT NULL;
